/* @lc app=leetcode id=2121 lang=kotlin */ class Solution { fun getDistances(arr: IntArray): LongArray = LongArray(arr.size).let { ans -> IntArray(100005).let { lC -> LongArray(100005).let { lS -> IntArray(100005).let { rC -> LongArray(100005).let { rS -> (0 until arr.size).forEach { i -> arr[i].let { x -> x.also { ans[i] += lC[x].toLong() * i - lS[x] }.also { lC[x]++ }.also { lS[x] += i } } }.run { (arr.size - 1 downTo 0).forEach { i -> arr[i].let { x -> x.also { ans[i] += rS[x] - rC[x].toLong() * i }.also { rC[x]++ }.also { rS[x] += i } } } }.run { ans } } } } } } }